def boundary208(env):
    xy = env.scene['robot'].data.root_pos_w[:, :2] - env.scene.env_origins[:, :2]
    return (xy[:, 0] < COURSE_X[0]) | (xy[:, 0] > COURSE_X[1]) | (
        xy[:, 1] < COURSE_Y[0]) | (xy[:, 1] > COURSE_Y[1])

def declared_truncation_terms(tm):
    declared={n:bool(tm.get_term_cfg(n).time_out) for n in tm.active_terms}
    assert set(n for n,v in declared.items() if v)==TRUNCATION_TERMS,('Unexpected truncation declaration',declared)
    assert {'closure','mimic'}.issubset(declared) and not declared['closure'] and not declared['mimic']
    return declared

def route_for_env(env_id):
    if type(env_id) is not int or env_id < 0:
        raise ValueError('Invalid original environment ID')
    reverse = bool(env_id % 2)
    return dict(route='rough_reverse' if reverse else 'rough_forward',
                spawn_ground_xy=(ROUTE_X[int(reverse)], ROUTE_Y),
                spawn_heading=math.pi if reverse else 0.,
                target_x=ROUTE_X[int(not reverse)])

def rm70_eligibility(env,ids):
 # All routes are this new original-CAD rough lesson. No certification of an
 # old plane cell, no actor terrain mask, and no forced yaw/velocity correction.
 return (torch.zeros(len(ids),device=env.device,dtype=torch.bool),
         torch.full((len(ids),),4,device=env.device,dtype=torch.long))

class RetentionLearningEnv(E1ResetEvidenceLearningEnv):
 def __init__(self,*a,**k):
  super().__init__(*a,**k);self._retention_trace=[];self._retention_trace_written=0;self._retention_trace_files=[]
 def step(self,action):
  cmd=self.command_manager.get_term('twist');before=tensor(self.scene['robot'].data.root_pos_w).clone();heading=tensor(self.scene['robot'].data.heading_w).clone();command=cmd.command.clone();modes=torch.stack((cmd.family,cmd.eligible_flat.long(),cmd.linear.long(),cmd.moving.long()),1).clone()
  result=super().step(action);after=self._e1_pre_reset_frame['root'][:,:3]
  # Each transition uses the command that produced it and pre-reset root.
  row=torch.cat((before,after,heading[:,None],command,modes.float(),self.termination_manager.terminated[:,None],self.termination_manager.time_outs[:,None]),1)
  self._retention_trace.append(row.cpu().numpy());return result
 def write_retention_trace(self,directory):
  p=Path(directory);p.mkdir(exist_ok=True);end=len(self._retention_trace)
  if end>self._retention_trace_written:
   name='retention_prefix_'+str(self._retention_trace_written)+'_'+str(end)+'.npz';q=p/name;assert not q.exists()
   np.savez_compressed(q,rows=np.stack(self._retention_trace[self._retention_trace_written:end]),columns=np.array(['before_x','before_y','before_z','pre_reset_x','pre_reset_y','pre_reset_z','heading_before','BODY_vx','BODY_vy','signed_yaw','family','eligible','linear','moving','terminated','truncated']))
   self._retention_trace_files.append(name);self._retention_trace_written=end
  (p/'RETENTION_COMMAND_ACTUAL.json').write_text(json.dumps(dict(actual_controls=end,trace_files=self._retention_trace_files,audit=self.command_manager.get_term('twist').audit_retention(),pre_reset_roots_no_teleport=True,complete_cycles_not_claimed_from_truncated_prefixes=True),indent=2))

class E1TerrainLearningEnv(E1ChassisTerrainEnv):
 def __init__(self,*args,**kwargs):
  super().__init__(*args,**kwargs)
  self._e1_episode=torch.zeros(self.num_envs,device=self.device,dtype=torch.long)
 def _reset_idx(self,ids):
  super()._reset_idx(ids)
  if hasattr(self,'_e1_episode'):
   self._e1_episode[ids]+=1
   self._rough_query_tick=None

class E1ResetEvidenceLearningEnv(E1TerrainLearningEnv):
    def _reset_idx(self, ids):
        super()._reset_idx(ids)
        if hasattr(self,'_rough_probe_expected_q'):
            bind_expected_reset_q(self,ids)

class DelayedJointVelocityAction(_DelayMixin, mdp_actions.JointVelocityAction):
    def __init__(self, cfg, env):
        super().__init__(cfg, env)
        self._init_delay(ACTION_DELAY_MIN, ACTION_DELAY_MAX, DELAY_HOLD_PROB, DELAY_PERIOD)

def linear_exp(env, command_name='twist', std=.25):
    # Keep the legacy parameter name for the Isaac manager interface only.
    return exponential(forward_error(env,command_name).square(),std)

def yaw_exp(env, command_name='twist', std=.25):
    error=env.command_manager.get_command(command_name)[:,2]-env.scene['robot'].data.root_ang_vel_b[:,2]
    return exponential(error.square(),std)

def _update_command(self):
        super()._update_command()
        if not self.manual_evaluation_mode:
            self._write_dynamic(torch.arange(self.num_envs, device=self.device))
            self.phase_elapsed += self._dt

class PhysicalActionDelayAdapter:
    def __init__(self,env,enabled,seed,collect=False):
        assert env.physics_dt==.0025 and env.step_dt==.02 and env.cfg.decimation==8
        assert not getattr(env.sim,'_physics_handles_decimation',False)
        self.env=env;self.queue=PhysicsActionQueue(env.num_envs,env.device,seed,enabled=enabled,control_us=int(os.environ["MOD4_RESUME_QUEUE_CONTROL_US"]))
        self.collect=collect;self.rows={k:[] for k in WIDTHS};self.calls={k:0 for k in WIDTHS}
        self.reset_rows=[];self.formula_max_error=0.;self.terms={}
        for key,width in WIDTHS.items():
            term=env.action_manager.get_term(key);assert term.action_dim==width and term._max_lag==0
            self.terms[key]=term
            self._wrap(key,term)
    def ids(self,env_ids):
        allids=torch.arange(self.env.num_envs,device=self.env.device)
        return allids if env_ids is None else allids[env_ids] if isinstance(env_ids,slice) else torch.as_tensor(env_ids,device=self.env.device,dtype=torch.long)
    def neutral(self,key):
        term=self.terms[key]
        if key=='legs':return as_tensor(term._asset.data.default_joint_pos)[:,term._joint_ids].clone()
        return torch.zeros((self.env.num_envs,2),device=self.env.device)
    def _wrap(self,key,term):
        original_process=term.process_actions;original_apply=term.apply_actions;original_reset=term.reset
        adapter=self
        def process(this,actions):
            original_process(actions)
            adapter.queue.submit(key,this.processed_actions.clone(),int(adapter.env._sim_step_counter))
        def apply(this):
            # Installed SDK increments the counter immediately before this call;
            # the integration interval has not begun yet.
            tick=int(adapter.env._sim_step_counter)-1
            original=this._processed_actions
            value=adapter.queue.apply(key,tick)
            this._processed_actions=value
            try:original_apply()
            finally:this._processed_actions=original
            field='joint_pos_target' if key=='legs' else 'joint_vel_target'
            actual=as_tensor(getattr(this._asset.data,field))[:,this._joint_ids]
            error=float((actual-value).abs().max());adapter.formula_max_error=max(adapter.formula_max_error,error)
            assert error<=1e-6,'Actual articulation target differs from selected delayed target'
            adapter.calls[key]+=1
            if adapter.collect:
                row={name:(item.detach().cpu().tolist() if torch.is_tensor(item) else item) for name,item in adapter.queue.receipt(key,tick).items()}
                row.update(requested_processed_target=original.detach().cpu().tolist(),actual_processed_target=value.detach().cpu().tolist(),actual_articulation_target=actual.detach().cpu().tolist())
                adapter.rows[key].append(row)
        def reset(this,env_ids=None):
            original_reset(env_ids)
            selected=adapter.ids(env_ids)
            old=adapter.queue.state_dict() if adapter.collect else None
            adapter.queue.reset(key,selected,adapter.neutral(key))
            if adapter.collect:
                others=torch.ones(adapter.env.num_envs,dtype=torch.bool,device=adapter.env.device);others[selected]=False
                g=adapter.queue.groups[key]
                assert all(torch.equal(g[f][others],old['groups'][key][f][others]) for f in g)
                assert torch.equal(g['last_apply_tick'],old['groups'][key]['last_apply_tick'])
                assert torch.equal(g['applied'][selected],adapter.neutral(key)[selected]) and not bool(g['pending_valid'][selected].any())
                adapter.reset_rows.append(dict(group=key,env_ids=selected.cpu().tolist(),unselected_exact=True,global_physics_clock_preserved=True,selected_stale_pending_cleared=True,neutral_target_from_actual_default_q_or_zero_wheel=True))
        term.process_actions=types.MethodType(process,term);term.apply_actions=types.MethodType(apply,term);term.reset=types.MethodType(reset,term)
        self.queue.reset(key,self.ids(None),self.neutral(key))
    def state_dict(self):return self.queue.state_dict()
    def load_state_dict(self,state):self.queue.load_state_dict(state)
    def audit(self):
        return dict(recipe=self.queue.recipe(),callback_counts=self.calls,application_formula_max_error=self.formula_max_error,rows=self.rows,reset_rows=self.reset_rows,policy_requested_processed_targets_restored_after_apply=True,original_legacy_delay_remains_disabled=True,actual_apply_time_is_before_integration=True,actual_apply_time_counter_minus1=True,not_training_or_full_DR_graduation=True)

